import React, { Ref } from 'react';
import { useProgressTrackerContext } from '../../../../ProgressTrackerContext';
import {
  StyledIconCompleted,
  StyledIconError,
  StyledStepCicleButton,
  StyledStepCicleLabel,
  StyledStepContainer,
  StyledStepContentContainer,
  StyledStepLabelsContainer,
} from './Step.styles';
import StepContext from './StepContext';
import { StepProps } from './Step.types';

const Step = React.forwardRef(
  (
    { index, completed = false, error = false, disabled = false, children, onSelect }: StepProps,
    forwardedRef: Ref<HTMLButtonElement>
  ): JSX.Element => {
    const contextValue = React.useMemo(
      () => ({ index, completed, error, disabled }),
      [index, completed, error, disabled]
    );

    const progressTrackerContext = useProgressTrackerContext();

    if (!progressTrackerContext) {
      // eslint-disable-next-line no-console
      console.warn(
        'Make sure of ProgressTracler.Step component is subcomponent of ProgressTracker.Header and ProgressTracker.Root.'
      );
      return <></>;
    }

    const { size, orientation, currentStep } = progressTrackerContext;

    const renderStepCicleContent = () => {
      if (error && !isActiveStep()) {
        return <StyledIconError size={size} />;
      }
      if (completed && !isActiveStep()) {
        return <StyledIconCompleted size={size} />;
      }
      return (
        <StyledStepCicleLabel clickable={isClickableStep()} size={size}>
          {index + 1}
        </StyledStepCicleLabel>
      );
    };

    const isActiveStep = () => currentStep === index;

    const handlePressSpace = (event: React.KeyboardEvent<HTMLButtonElement>) => {
      const isSpace = event.key === 'Space';
      if (isSpace) {
        onStepHandler();
      }
    };

    const accessibleMessage = () => {
      let message = `Step button, position ${index + 1}.`;
      if (disabled) {
        message += 'Step disabled.';
      } else if (error && !isActiveStep()) {
        message += 'Step with error.';
      } else if (completed && !isActiveStep()) {
        message += 'Step completed.';
      }
      return message;
    };

    const onStepHandler = () => isClickableStep() && onSelect?.(index);
    const isClickableStep = () => !disabled && !!onSelect;
    return (
      <StepContext.Provider value={contextValue}>
        <StyledStepContainer data-testid="step-container">
          <StyledStepContentContainer orientation={orientation}>
            <StyledStepCicleButton
              ref={forwardedRef}
              aria-label={accessibleMessage()}
              aria-disabled={disabled}
              aria-invalid={error}
              aria-current={isActiveStep()}
              disabled={disabled}
              completed={completed && !isActiveStep()}
              error={error && !isActiveStep()}
              size={size}
              clickable={isClickableStep()}
              active={isActiveStep()}
              onKeyDown={handlePressSpace}
              onClick={() => onStepHandler()}
            >
              {renderStepCicleContent()}
            </StyledStepCicleButton>
            {children && (
              <StyledStepLabelsContainer orientation={orientation}>
                {children}
              </StyledStepLabelsContainer>
            )}
          </StyledStepContentContainer>
        </StyledStepContainer>
      </StepContext.Provider>
    );
  }
);

export default Step;
